package com.gathin.tvhome;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import org.json.*;

/** Foreground-only local sources, with honest actions rather than promised playback. */
public final class WatchTonightActivity extends Activity {
    private java.util.concurrent.ThreadPoolExecutor worker;private LinearLayout rows;private int section,generation;private CancellationSignal cancel;private boolean active;private String profile;private Config config;
    protected void attachBaseContext(Context c){super.attachBaseContext(LauncherLocale.wrap(c));}
    protected void onResume(){super.onResume();active=true;worker=new java.util.concurrent.ThreadPoolExecutor(1,1,0L,java.util.concurrent.TimeUnit.MILLISECONDS,new java.util.concurrent.ArrayBlockingQueue<>(2),new java.util.concurrent.ThreadPoolExecutor.DiscardOldestPolicy());config=Config.load(this);profile=ProfileStore.id();render();}
    protected void onPause(){active=false;if(worker!=null)worker.shutdownNow();generation++;if(cancel!=null)cancel.cancel();super.onPause();}
    private void render(){int requested=section;int run=++generation;if(cancel!=null)cancel.cancel();cancel=new CancellationSignal();CancellationSignal signal=cancel;
        LinearLayout page=FreedomUi.body(this);page.setBackgroundColor(getColor(R.color.freedom_canvas));TextView heading=FreedomUi.text(this,"Watch tonight",28);heading.setTypeface(ThemeTone.heading(this));heading.setTextColor(ThemeTone.accent(this));page.addView(heading);page.addView(FreedomUi.text(this,"Continue where an app shares a link, revisit your watchlist, or open a service.",16));
        LinearLayout tabs=new LinearLayout(this);page.addView(tabs);String[] names={"Continue","Watchlist","Services"};TextView[] buttons=new TextView[3];for(int i=0;i<3;i++){final int at=i;LinearLayout slot=new LinearLayout(this);tabs.addView(slot,new LinearLayout.LayoutParams(0,-2,1));buttons[i]=FreedomUi.action(this,slot,(section==i?"• ":"")+names[i],()->{section=at;render();});}
        ScrollView scroll=new ScrollView(this);rows=new LinearLayout(this);rows.setOrientation(LinearLayout.VERTICAL);scroll.addView(rows);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));FreedomUi.action(this,page,"Back to Home",this::finish);setContentView(page);buttons[section].requestFocus();
        Map<String,HomeCategories.App> visible=new LinkedHashMap<>();for(HomeCategories.App app:HomeCategories.catalog(this,config))if(LibraryVisibility.allowed(this,app.pkg)&&FamilyMode.allowed(this,app.pkg))visible.put(app.pkg,app);
        if(section==2){for(HomeCategories.App app:visible.values())FreedomUi.action(this,rows,"Open "+app.label,()->app.launch(this,config));if(visible.isEmpty())message("No visible apps in this profile.");return;}
        if(section==1&&FamilyMode.active(this)){message("The shared household watchlist is unavailable in a child-friendly Home. A parent can review Discover outside this profile.");return;}
        if(section==0&&!ContentShelves.enabled(this)){message("Continue is off for this profile. Some services share no titles even when enabled.");FreedomUi.action(this,rows,"Review content-shelf access",()->ContentShelves.settings(this));return;}
        message("Reading local titles…");worker.getQueue().clear();worker.execute(()->{if(signal.isCanceled())return;List<ContentShelves.Card> cards=Collections.emptyList();String watch="[]";boolean shared=false,unavailable=false;try{if(requested==0){boolean[] missing={false};cards=ContentShelves.read(this,signal,visible,missing);unavailable=missing[0];}else if(getPackageManager().checkSignatures(getPackageName(),OptionalPanels.HUB)==PackageManager.SIGNATURE_MATCH){Bundle b=getContentResolver().call(OptionalPanels.URI,"watchlist",null,null);if(b!=null){shared=b.getBoolean("shared",false);watch=b.getString("items","[]");}}}catch(RuntimeException absent){unavailable=true;}final List<ContentShelves.Card> result=cards;final String list=watch;final boolean enabled=shared,missing=unavailable;runOnUiThread(()->{if(!active||generation!=run||signal.isCanceled()||!profile.equals(ProfileStore.id()))return;rows.removeAllViews();if(section==0){int count=0;for(ContentShelves.Card card:result)if(card.watchNext){count++;FreedomUi.action(this,rows,card.title+"\nContinue in "+card.app.label+(card.progress>=0?" · "+card.progress+"%":""),()->{try{startActivity(card.intent);}catch(RuntimeException absent){Toast.makeText(this,"That app no longer accepts this link. Open it and search for the title.",Toast.LENGTH_LONG).show();}});}if(count==0)message(missing?"This TV did not provide Continue titles. Your apps and accounts are unchanged.":"No Continue titles shared by your visible apps.");}else{if(!enabled){message("Watchlist sharing is off. Turn it on explicitly in Companions → Discover → Your watchlist. No account or browsing access is enabled here.");FreedomUi.action(this,rows,"Open Discover",()->openDiscover(null));}else try{JSONArray items=new JSONArray(list);int count=0;for(int i=0;i<Math.min(100,items.length());i++){JSONObject item=items.optJSONObject(i);if(item==null)continue;String token=item.optString("token"),title=item.optString("title");if(!WatchTonightPolicy.valid(token,title))continue;count++;FreedomUi.action(this,rows,title+"\nDetails & services",()->openDiscover(token));}if(count==0)message("Your shared watchlist is empty. Save a title in Discover first.");}catch(JSONException invalid){message("Watchlist unavailable. Open Discover to review it.");}}});});
    }
    private void message(String text){rows.addView(FreedomUi.text(this,text,17));}
    private void openDiscover(String token){try{if(getPackageManager().checkSignatures(getPackageName(),OptionalPanels.HUB)!=PackageManager.SIGNATURE_MATCH)throw new SecurityException();Intent i=new Intent().setComponent(new ComponentName(OptionalPanels.HUB,OptionalPanels.HUB+".DiscoverActivity"));if(token!=null)i.putExtra("title_token",token);startActivity(i);}catch(RuntimeException absent){Toast.makeText(this,"Install the matching DV Freedom Companions app from Setup.",Toast.LENGTH_LONG).show();}}
}
